draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50, 0, 2 * Math.PI);
  ctx.fillStyle = 'yellow';
  ctx.fill();
  ctx.stroke();

  // cloud
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t) * 100, H / 2 - 50, 30, 0, 2 * Math.PI);
  ctx.fillStyle = 'white';
  ctx.fill();
  ctx.stroke();

  // tree
  ctx.beginPath();
  ctx.moveTo(W / 2, H - 50);
  ctx.lineTo(W / 2, H - 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2, H - 150, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // birds
  ctx.beginPath();
  ctx.arc(W / 2 - 100 + Math.sin(t) * 50, H / 2 - 100, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + 100 + Math.cos(t) * 50, H / 2 - 100, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
